WITH requested(user_id) AS ( VALUES
(#{userId})
) SELECT encode(u.id, 'hex') AS "id", u.user_id AS "userId", encode(u.coupon_template_id, 'hex') AS "couponTemplateId", u.status, u.valid_start_at AS "validStartAt", u.valid_end_at AS "validEndAt", u.received_at AS "receivedAt", u.locked_order_no AS "lockedOrderNo", u.locked_at AS "lockedAt", u.used_order_no AS "usedOrderNo", u.used_at AS "usedAt", u.version, u.created_at AS "createdAt", u.updated_at AS "updatedAt" FROM user_coupon u INNER JOIN requested r ON r.user_id = u.user_id
WHERE u.status = #{status}
ORDER BY u.received_at DESC, u.created_at DESC

WITH requested(id) AS ( VALUES
(#{id})
) SELECT encode(u.id, 'hex') AS "userCouponId", u.user_id AS "userId", encode(u.coupon_template_id, 'hex') AS "couponTemplateId", u.status AS "status", u.valid_start_at AS "validStartAt", u.valid_end_at AS "validEndAt", u.received_at AS "receivedAt", u.locked_order_no AS "lockedOrderNo", u.locked_at AS "lockedAt", u.used_order_no AS "usedOrderNo", u.used_at AS "usedAt", u.version AS "version", u.created_at AS "createdAt", u.updated_at AS "updatedAt" FROM user_coupon u INNER JOIN requested r ON r.id = u.coupon_template_id WHERE u.user_id = #{userId} ORDER BY u.received_at DESC, u.created_at DESC

SELECT encode(uc.id, 'hex') AS "userCouponId", encode(uc.coupon_template_id, 'hex') AS "couponTemplateId", uc.user_id AS "userId", uc.status AS status, uc.received_at AS "receivedAt", uc.valid_start_at AS "validStartAt", uc.valid_end_at AS "validEndAt", uc.locked_order_no AS "lockedOrderNo", uc.locked_at AS "lockedAt", uc.used_order_no AS "usedOrderNo", uc.used_at AS "usedAt", uc.created_at AS "createdAt" FROM user_coupon uc WHERE uc.coupon_template_id = #{couponTemplateId}
AND uc.status = #{status}
AND uc.user_id = #{userId}
ORDER BY uc.received_at DESC, uc.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

